"""Create the illustrated PDF and editable Markdown study report."""
from pathlib import Path
import json,html
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Image,Table,TableStyle,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.utils import ImageReader
R=Path(__file__).resolve().parent
def main():
    summary=json.loads((R/'results/summary.json').read_text());qa=json.loads((R/'results/validation.json').read_text());meta=json.loads((R/'data/metadata.json').read_text());tx=json.loads((R/'data/transmitters.json').read_text())
    ss=getSampleStyleSheet();ss.add(ParagraphStyle(name='Body2',fontName='Helvetica',fontSize=10.3,leading=15,spaceAfter=9,textColor=colors.HexColor('#25364a')))
    ss.add(ParagraphStyle(name='Title2',fontName='Helvetica-Bold',fontSize=25,leading=29,spaceAfter=15,textColor=colors.HexColor('#15334c')))
    ss.add(ParagraphStyle(name='Head2',fontName='Helvetica-Bold',fontSize=15,leading=20,spaceAfter=10,textColor=colors.HexColor('#15334c')))
    ss.add(ParagraphStyle(name='Small2',fontName='Helvetica',fontSize=8.4,leading=11,spaceAfter=7,textColor=colors.HexColor('#4a5c6c')))
    story=[];md=[]
    def p(s,small=False):story.append(Paragraph(s,ss['Small2' if small else 'Body2']));md.append(s.replace('<b>','**').replace('</b>','**'))
    def heading(s,first=False):story.append(Paragraph(s,ss['Title2' if first else 'Head2']));md.append(('# ' if first else '## ')+s)
    def page(s):
        if story:story.append(PageBreak())
        heading(s,True)
    def img(file,width=490):
        path=R/'figures'/file;w,h=ImageReader(str(path)).getSize();story.append(Image(str(path),width=width,height=width*h/w));story.append(Spacer(1,8));md.append(f'![{file}](figures/{file})')
    def table(rows,widths):
        rows2=[[Paragraph(html.escape(str(c)),ss['Small2']) for c in row] for row in rows]
        t=Table(rows2,colWidths=widths,hAlign='LEFT',repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e6eef3')),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#cbd5dd')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.append(t);story.append(Spacer(1,12));md.append('\n'.join(['| '+' | '.join(str(c) for c in row)+' |' for row in rows[:1]]+['| '+' | '.join('---' for _ in rows[0])+' |']+['| '+' | '.join(str(c) for c in row)+' |' for row in rows[1:]]))
    page("Edinburgh King's Buildings radio study")
    p('Campus geometry, outdoor propagation and reproducible Sionna experiments | 04 October 2026',True)
    p('A three-site rooftop scenario increases outdoor signal coverage while introducing cochannel interference. At 3.5 GHz, the modeled area above -85 dBm rises from <b>54.4% to 77.4%</b>; <b>61.6%</b> meets both the signal target and a 5 dB SINR target. The study evaluates these configurations with Sionna RT 2.2.0 using the geometry, antenna and propagation settings documented below.')
    img('campus_overview.png',485)
    p('The orange line defines the 18.93 ha OSM campus polygon used for scoring; letters mark hypothetical rooftop transmitters. The surrounding rectangle provides terrain and building context. The university describes a wider 35 ha estate [2].',True)
    p('Deliverables include an offline interactive explorer, Mitsuba XML and PLY meshes, an OBJ model, geographic features, raw per-site gains, cell-level tables, figures, validation results, and all study code. The goal is a useful starting point for campus wireless research and field calibration.')

    page('What Sionna and the large map project do')
    p('Sionna RT traces electromagnetic propagation through a triangle-mesh scene. Geometry determines visibility and interactions; material properties and antennas determine how power is transported. A radio map averages path gain over surface cells, producing predictions for the specified scene and radio configuration [3,4].')
    p('NVIDIA\'s large-radio-maps project adds geographic orchestration around Sionna RT [1]. It subdivides a region according to transmitter density, builds terrain and building scenes, selects nearby stations, and computes each tile. Tile outputs can be scheduled across a SLURM GPU cluster. The campus is small enough for one buffered scene, so adaptive subdivision would add complexity without a demonstrated benefit here.')
    table([['Component','Upstream source behavior','This campus experiment'],['Scene construction','OSM buildings, terrain tiles, adaptive terrain meshes and buffers','OSM ways and multipolygons, terrain tiles, regular 10 m terrain mesh'],['Coordinates','UTM with tile southwest origin; terrain elevation retained','UTM 30N minus a documented local origin and elevation reference'],['Station placement','CSV plus optional raycast elevation and rooftop/ground offsets','Three named-roof representative points; antenna 3 m above modeled roof'],['Radio maps','Mesh measurement surface; memory-aware passes; maximum site gain','Same terrain-surface concept; retain every site gain for RSS, SINR and association'],['Runtime','Source pins Sionna RT 1.2.1; GPU memory estimator and SLURM examples','Sionna RT 2.2.0; actual LLVM CPU runs']], [83,204,203])
    heading('Integration findings from source inspection')
    p('The README describes a height column, but BaseStationDB.from_file requires elevation. Rooftop elevations receive a further 2 m offset, and non-rooftop locations default to a 25 m offset. A site\'s reported altitude must therefore be interpreted before import. The code also applies a deterministic index-seeded random azimuth; this is reproducible but does not establish a real antenna orientation.')
    p('The default upstream antenna is a 2-by-16 TR38901 array and its map computation keeps the maximum linear path gain over sites. Interference analysis requires the individual site gains, so this study preserves the full site-by-triangle tensor. The campus experiment uses its own Sionna RT 2.2.0 runner; the upstream 1.2.1 export and execution conventions are covered in the integration section.')

    page('Geographic definition and model evidence')
    p('King\'s Buildings offers a named science and engineering campus, published university maps, and identifiable buildings [2,5]. The study mask is OSM way 9514792 [6]. Its polygon is used as a reproducible mapped extent, not a legally verified estate boundary.')
    table([['Quantity','Value'],['Scored campus polygon','189,297 m2 / 18.93 ha'],['Ground rectangle','990 m east-west x 750 m north-south'],['SW corner, latitude longitude','55.91920421, -3.18218766'],['NE corner, latitude longitude','55.92596538, -3.16637605'],['Local coordinate origin','55.922000 N, -3.175000 E; EPSG:32630'],['Local UTM origin, metres','E 489063.667, N 6197412.288'],['Vertical subtraction from source terrain','80.738 m; source datum not independently surveyed'],['Building parts / campus building parts','855 / 66'],['Building / measurement triangles','19,044 / 14,850'],['Outdoor campus triangles scored','2,584; centroid mask, surface-area weighting']], [215,275])
    p('OSM was retrieved with a database timestamp of 2026-10-04 21:52:50 UTC. Complete way rings and multipolygon courtyards are assembled before triangulation. Roof triangle areas are checked against footprint areas. Outlines are extruded with flat roofs; foundations extend 0.5 m below the minimum sampled ground elevation, and roofs sit one modeled building height above the highest sampled footprint ground point.')
    p('Of the 66 campus building parts, only <b>5 have explicit height tags</b>; 44 use mapped storey counts multiplied by an assumed 3.5 m per storey, and 17 default to 10.5 m. Across the full surroundings, 535 of 855 parts use the fallback. Even explicit OSM heights are not independently surveyed. Exact roof shape, facade segmentation, windows and rooftop equipment are absent.')
    p('Terrain comes from the public Mapzen / Tilezen elevation tiles [7,8], decoded from Terrarium RGB and interpolated onto the mesh. The 10 m mesh spacing is computational resolution, not evidence that the source terrain is accurate to 10 m or that its vertical datum matches a local survey. Trees, vehicles, interior layouts and building parts tagged only as building:part are not modeled.')

    page('Experiment specification and metrics')
    table([['Site','Proposed building','Latitude','Longitude','Local z m'],*[[t['id'],t['name'],f"{t['lat']:.6f}",f"{t['lon']:.6f}",f"{t['z']:.2f}"] for t in tx]],[29,224,78,78,81])
    p('Each site is a hypothetical point 3 m above its modeled roof, chosen by an interior representative point of the footprint. The positions are not evidence of installed equipment or approved mounting locations. Relative z is measured from the documented vertical reference, not directly above local ground.')
    table([['Parameter','Chosen setting'],['Frequencies','2.4, 3.5 and 5.8 GHz'],['Antenna / power','One isotropic V-polarized element; 30 dBm per site'],['Propagation','LOS and specular reflection; maximum depth 3'],['Disabled effects','Diffuse reflection, diffraction, refraction and external interference'],['Materials','All buildings ITU concrete; all terrain ITU wet ground'],['Measurement height','Terrain mesh translated vertically by 1.5 m'],['Sampling','20 million rays per site per run; seeds 17 and 29'],['Noise model','20 MHz bandwidth, 7 dB noise figure, -174 dBm/Hz'],['Scoring targets','RSS >= -85 dBm and SINR >= 5 dB']], [170,320])
    p('Let g(i,t) be the linear path gain from transmitter t to terrain triangle i. Received power in mW is p(i,t) = 10^(P(t)/10) g(i,t), with P in dBm. Best-site RSS is 10 log10(max p). Noise is 10^((-174 + 10 log10(20,000,000) + 7)/10) mW, approximately -94 dBm. Full-load reuse-one SINR is best p divided by the sum of other site powers plus noise. With one active site it becomes SNR.')
    p('The scored percentage is the sum of passing terrain-triangle surface areas divided by all outdoor campus-triangle surface areas. A triangle is classified using its centroid. This is not exact polygon clipping and is coarse near walls and boundary edges. RSS is total received power, <b>not RSRP</b>; no bandwidth-to-throughput claim is made. Three active sites use three times the total transmit power of the one-site case.')
    p('The selected ITU wet-ground material model covers 1-10 GHz in the installed implementation. The three study frequencies fall within that range.',True)

    page('Results and what they imply')
    img('radio_comparison.png',490)
    p('3.5 GHz results. Grey footprints are excluded from outdoor scoring. Low or zero sampled gains are shown at the dark end of the display scale. The third panel includes cochannel interference from the two non-serving sites.',True)
    table([['GHz','Active layout','RSS target %','SINR target %','Both targets %'],*[[str(r['frequency_ghz']), 'A only' if r['layout']=='single_A' else 'A + B + C',f"{r['rss_ge_minus85_dbm_pct']:.1f}",f"{r['sinr_ge_5_db_pct']:.1f}",f"{r['joint_rss_sinr_pct']:.1f}"] for r in summary]],[47,128,105,105,105])
    p('At 3.5 GHz, adding B and C improves received-power reach by about 23 percentage points. The joint target improves by only about 7 percentage points because sites also interfere when cochannel and fully loaded. This supports testing channel coordination, directional patterns or power control before interpreting extra signal strength as an equivalent service improvement.')
    p('The identical-power comparison favors 2.4 GHz in received-power reach: three sites cover about 82.1% above the chosen RSS threshold, versus 77.4% at 3.5 GHz and 72.7% at 5.8 GHz. It does not compare actual Wi-Fi and cellular systems, regulatory power limits, antenna apertures, bandwidths, traffic scheduling, or device performance.')
    p('Large shadows remain around modeled building masses and some campus edges. About 14.5% of the outdoor surface has zero sampled gain from all three sites in the main run. Missing diffraction, material simplification and limited ray sampling can contribute to such cells. They are candidate locations for further modeling and measurements, not certified dead zones.')

    page('Numerical checks and confidence limits')
    conv=qa['sample_convergence'];los=qa['los_ablation']
    table([['Check at 3.5 GHz','Result'],['20M vs 40M rays per site per seed',f"RSS target area {conv['base_rss_ge_minus85_pct']:.2f}% vs {conv['comparison_rss_ge_minus85_pct']:.2f}%"],['Absolute change in target area',f"{abs(conv['base_rss_ge_minus85_pct']-conv['comparison_rss_ge_minus85_pct']):.2f} percentage points"],['Both-positive cells, absolute gain delta',f"Median {conv['median_abs_delta_db_both_positive']:.3f} dB; 95th percentile {conv['p95_abs_delta_db_both_positive']:.2f} dB"],['Largest both-positive change',f"{conv['max_abs_delta_db_both_positive']:.2f} dB"],['Zero/nonzero disagreement',f"{conv['zero_state_disagreement_pct']:.2f}% of outdoor surface"],['LOS-only vs depth-three reflections',f"{los['los_only_rss_ge_minus85_pct']:.1f}% vs {los['depth3_rss_ge_minus85_pct']:.1f}% above RSS target"]],[215,275])
    p('The main aggregate target percentage is relatively stable to this doubling of samples, but the maximum change and zero-state disagreement show that weak cells remain uncertain. Seed repeats alone are not a sufficient convergence test: deterministic ray directions and specular components can make seed changes have little effect. No confidence interval is inferred from only two seeds.')
    img('rss_distribution.png',420)
    p('The distribution includes zero-gain cells below the plotted range. The dashed line is the study RSS threshold. These plots and the LOS ablation show that the outcome depends strongly on modeled specular paths, which makes facade-material and geometry validation particularly valuable.',True)
    p('Checks passed for finite mesh coordinates, terrain face orientation and area, local UTM round-trip consistency, nonnegative finite gains, and tensor-to-mesh dimensions. Roof triangulation preserved polygon area. This is computational QA; no drive test, walk test, LiDAR comparison, receiver calibration, material fitting or independent propagation-engine validation has been completed.')

    page('Reproduction and scaling to Edinburgh')
    p('The supplied outputs can be explored immediately without running a simulator. For regeneration, use Python 3.12, install requirements.txt into an isolated environment, and follow README.md. Build the scene, run the main frequencies plus LOS and 40M checks, validate, export the LRM layout, analyze, and regenerate this report. The OSM and terrain snapshots are included so network refreshes are optional and deliberate.')
    p('The computation used Sionna RT 2.2.0 with Mitsuba 3.9.1 and the LLVM CPU backend on Windows x64, with the official LLVM 21.1.8 library. A compatible NVIDIA GPU provides an alternative backend for larger studies. The reproduction guide records dependency versions and backend setup.')
    heading('Files that preserve scientific traceability')
    p('The raw radio NPZ files retain linear path_gain[site, triangle] and seed_gains[seed, site, triangle], plus frequency, sample count and seeds. Measurement vertices, face indices, centroids, areas and the outdoor mask are stored separately. The per-cell CSVs expose all three gains, strongest RSS and full-load SINR; zero-gain dB fields are blank. The figure and report builders recompute summaries from these files.')
    p('Source data checksums and OSM timestamps are recorded under data/. Geographic feature files use WGS84; the explicitly named local file uses metric local coordinates. NOTICE.md links the geographic and software sources and records their attribution. The study code uses the MIT license; geographic inputs retain their source terms. The NVIDIA pipeline is available from its upstream repository under Apache 2.0.')
    heading('Native large-radio-maps handoff')
    p('export_lrm.py produces a numbered tile, bboxes.npz and a station CSV. Horizontal coordinates are shifted to the tile southwest corner and the vertical reference is restored. CSV elevation is the desired absolute antenna z minus the native 2 m rooftop offset. The native README\'s height/elevation naming inconsistency is documented rather than silently propagated.')
    p('The upstream pipeline pins Sionna RT 1.2.1 and uses GPU-memory estimation, different antennas, and max-over-sites output. Run it in a separate environment and verify frequency, offsets and solver flags before comparing results. The export geometry and schema were prepared, but the upstream 1.2.1 pipeline and cluster launch were not executed in this study.')
    p('To scale beyond the campus, use source-backed transmitter data and the upstream adaptive tiling workflow, retain geometry buffers across tile edges, and preserve per-site gains if interference is an objective. Validate overlaps with an untiled reference area before trusting stitched maps. GPU jobs, memory-aware passes and resumable work queues become useful only as scene size and station count grow.')

    page('Research plan and source register')
    heading('A practical next experiment')
    p('Begin with a campus walk test across open paths, courtyards and shadow edges. Record receiver height, antenna, frequency, bandwidth, transmit power, location accuracy and repeated readings. Reserve routes for evaluation rather than fitting every observation. Compare median error and error spread by LOS/NLOS condition; calibrate one model parameter group at a time.')
    p('Prioritize height verification for the 17 campus parts with assumed heights, then inspect the three candidate roofs and major obstruction edges. Replace the uniform facade and wet-ground assumptions with surveyed material groups and land cover. Add diffraction as a controlled ablation, and repeat the mesh at finer resolution. A 150 m buffer is a deliberate finite-domain choice, not a demonstrated convergence radius; repeat at 300 m or more before a deployment recommendation.')
    p('A creative research direction is a campus connectivity trail: evaluate signal, interference and site changes along pedestrian routes, then choose sites to maximize the worst-decile route quality under a fixed total-power budget. Compare cochannel, coordinated and directional scenarios. Keep accessibility, maintenance access and permissions as real-world constraints to resolve with the university, rather than inferring them from map geometry.')
    heading('Sources and attribution')
    refs=[('1','NVIDIA sionna-large-radio-maps source and README','https://github.com/NVlabs/sionna-large-radio-maps'),('2','University of Edinburgh campus location and wider site description','https://science-engineering.ed.ac.uk/about/location-map'),('3','Sionna RT radio-map solver documentation','https://nvlabs.github.io/sionna/rt/api/radio_map_solvers.html'),('4','Sionna RT radio-map definitions and metrics','https://nvlabs.github.io/sionna/rt/api/radio_maps.html'),('5','University campus maps','https://www.ed.ac.uk/maps'),('6','OSM mapped campus boundary','https://www.openstreetmap.org/way/9514792'),('7','AWS Terrain Tiles dataset register','https://registry.opendata.aws/terrain-tiles/'),('8','Tilezen terrain source attribution','https://github.com/tilezen/joerd/blob/master/docs/attribution.md'),('9','OpenStreetMap copyright and ODbL attribution','https://www.openstreetmap.org/copyright')]
    for n,label,url in refs:p(f'[{n}] {label}: <link href="{url}" color="#166187">{url}</link>',True)
    p('© OpenStreetMap contributors. Terrain data retain their underlying source attributions; NVIDIA code retains Apache 2.0. The experiment uses hypothetical transmitter sites and modeled building properties. Campus measurements provide the next step for calibration and evaluation.',True)
    def footer(c,doc):
        c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#647585'));c.drawString(42,26,"KING'S BUILDINGS / REPRODUCIBLE RADIO STUDY");c.drawRightString(553,26,str(doc.page))
    doc=SimpleDocTemplate(str(R/'report.pdf'),pagesize=(595.28,841.89),leftMargin=48,rightMargin=48,topMargin=42,bottomMargin=44,title="Edinburgh King's Buildings radio study",author='Mohamed Abuain')
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    (R/'report.md').write_text('\n\n'.join(md),encoding='utf8')
    print(R/'report.pdf')
if __name__=='__main__':main()
